def transform(grid):
    # Find a uniform horizontal line of 2s. It stays in place; copy the
    # colored shape on the opposite side of that line to the adjacent row.
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    line = next((r for r,row in enumerate(grid) if all(v == 2 for v in row)), None)
    if line is None:
        return out
    colors = {v for row in grid for v in row if v not in (2,)}
    bg = max(colors, key=lambda v: sum(x == v for row in grid for x in row))
    shape = [(r,c) for r in range(h) for c in range(w) if r != line and grid[r][c] not in (2,bg)]
    if not shape:
        return out
    # Move the object flush to the far side of the separator, leaving an 8
    # stripe in the row immediately before the relocated object.
    top = min(r for r,c in shape)
    bottom = max(r for r,c in shape)
    if top > line:
        dr = line + 1 - top
        stripe = bottom + dr + 1
    else:
        dr = line - 1 - bottom
        stripe = top + dr - 1
    for r,c in shape:
        out[r][c] = bg
    for r,c in shape:
        out[r+dr][c] = grid[r][c]
    if 0 <= stripe < h:
        out[stripe] = [8] * w
    return out
